async function r(n,t){return(n.headers.get("content-type")||"").includes("application/json")?(await n.json())?.detail||t:(await n.text()).trim()||t}async function s(){const n=await fetch("/api/auth/oidc/config");if(!n.ok)throw new Error("获取 OIDC 配置失败");return n.json()}async function i(n="/"){const t=new URLSearchParams({redirect_path:n}),o=await fetch(`/api/auth/oidc/login-url?${t}`);if(!o.ok){const e=await r(o,"获取 OIDC 登录地址失败");throw new Error(e)}return o.json()}async function c(n){const t=await fetch("/api/auth/oidc/exchange-code",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({code:n})});if(!t.ok){const o=await r(t,"OIDC 登录失败");throw new Error(o)}return t.json()}async function h(n){const t=await fetch("/api/auth/sms/send",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({phone_number:n})});if(!t.ok){const o=await r(t,"发送验证码失败"),e=new Error(o);throw e.status=t.status,e}return t.json()}async function p(n,t){const o=await fetch("/api/auth/sms/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({phone_number:n,code:t})});if(!o.ok){const e=await r(o,"验证码登录失败"),a=new Error(e);throw a.status=o.status,a}return o.json()}const u={getOIDCConfig:s,getOIDCLoginUrl:i,exchangeOIDCCode:c,sendSmsCode:h,smsLogin:p};export{u as a};
